const COACH_GLOBAL_MACRO = /\{\{\s*getglobalvar\s*::\s*Coach\s*\}\}/gi;

/**
 * Keep Weyland's global storytelling modifier out of WeyPhone-owned requests unless the user
 * explicitly opts this request type into an actively-enabled Hard Mode. Linked conversations are
 * generated by the main roleplay and never pass through this policy.
 */
export function applyPhoneHardModePolicy(content, {
    allowHardMode = false,
    hardModeEnabled = false,
} = {}) {
    const prompt = String(content ?? '');
    if (allowHardMode && hardModeEnabled) return prompt;
    return prompt.replace(COACH_GLOBAL_MACRO, '');
}

